src/components/InlineOrderBanner.astro.utf8Content:
---
import {site} from '../config/site';
---
<aside class="inline-order-banner" data-order-banner="inline" aria-label={`${site.brand} ${site.region} 주문 안내`}>
  <div class="inline-order-copy">
    <strong>{site.brand} {site.region} 주문 안내</strong>
    <span>전화 {site.phoneOrderHours} · 온라인 {site.onlineOrderHours} 접수</span>
    <small>상품과 문구가 고민되시면 편하게 문의해 주세요. 상담시간과 실제 전달시간은 다를 수 있어요. 원하시는 전달 일정과 반입 조건, 추가비용은 주문할 때 함께 확인해 주세요.</small>
  </div>
  <div class="inline-order-actions">
    <a class="inline-order-phone" href={site.phoneHref}>전화 상담 {site.phone}</a>
    <a class="inline-order-online" href={site.orderUrl}>{site.brand} 온라인 주문</a>
  </div>
</aside>
<style>
  .inline-order-banner{margin:32px 0;padding:24px;border:1px solid #ddc5d6;border-radius:16px;background:#fff6fa;box-shadow:0 8px 24px rgba(58,33,79,.04)}
  .inline-order-copy{display:flex;flex-direction:column;gap:8px}
  .inline-order-copy strong{font-size:20px;line-height:1.45;color:#3a214f}
  .inline-order-copy span{font-size:15px;line-height:1.65;color:#554c57}
  .inline-order-copy small{font-size:13px;line-height:1.7;color:#655568}
  .inline-order-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}
  .inline-order-actions a{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:11px 18px;border:1px solid #3a214f;border-radius:11px;font-size:15px;font-weight:800;line-height:1.5;text-decoration:none;overflow-wrap:anywhere}
  .inline-order-actions .inline-order-phone{background:#fff;color:#3a214f}
  .inline-order-actions .inline-order-online{background:#3a214f;color:#fff}
  @media(max-width:600px){.inline-order-banner{padding:20px 16px}.inline-order-actions{display:grid;grid-template-columns:1fr}.inline-order-actions a{width:100%}}
</style>

src/components/InlineText.astro.utf8Content:
---
import {inlineTokens} from '../lib/content.mjs';
const {text=''}=Astro.props;
---
{inlineTokens(text).map(token => token.type === 'strong' ? <strong>{token.text}</strong> : token.type === 'link' && token.href ? <a href={token.href}>{token.text}</a> : <Fragment>{token.text}</Fragment>)}

src/components/MarkdownContent.astro.utf8Content:
---
import {displayMarkdownBlocks} from '../lib/content.mjs';
import InlineText from './InlineText.astro';
const blocks=displayMarkdownBlocks(Astro.props.content || '', Astro.props.firstAnswer);
---
<div class="content-card markdown-content">{blocks.map(block => block.type === 'h2' ? <h2><InlineText text={block.text}/></h2> : block.type === 'h3' ? <h3><InlineText text={block.text}/></h3> : block.type === 'li' ? <ul><li><InlineText text={block.text}/></li></ul> : <p><InlineText text={block.text}/></p>)}</div>

src/components/ProductCards.astro.utf8Content:
---
import {site} from '../config/site';
const {products=[]}=Astro.props;
---
<div class="product-grid">{products.map((p:any)=><article class="product-card" data-product-family={p.family} data-product-key={p.key}><img src={p.img} alt={p.name} loading="lazy" width="420" height="420"/><div><h3>{p.name}</h3><strong>{p.price.toLocaleString()}원</strong><p>{p.desc}</p><a href={p.orderUrl || site.orderUrl}>상품 확인·주문 →</a></div></article>)}</div>
<p class="product-notice">{site.productVariationNotice} {site.deliveryNotice}</p>
{products.some((p:any)=>p.family==='congrats') && <p class="product-notice">사진 속 리본은 예시입니다. 이번 축하 자리에 전할 인사로 상담하세요.</p>}

src/components/RegionDirectory.astro.utf8Content:
---
import {site} from '../config/site';
import {groupsFor,coverage as sourceCoverage} from '../lib/regional-runtime.mjs';
import InlineOrderBanner from './InlineOrderBanner.astro';
const {pages}=Astro.props;
type Representative={pageKey:string;unitKeys:string[]};
type District={key:string;name:string;sourceUrl:string};
type RegionEntry={representative:Representative;page:{url:string;primaryKeyword:string;cardSummary:string}};
type RegionGroup=District & {items:RegionEntry[]};
type Coverage={districts:District[];units:{unitKey:string;name:string}[];administrativeCrosswalk:{aliasKey:string;name:string;districtKey:string;relations:{unitKey:string;scope:string}[]}[]};
const coverage=sourceCoverage as Coverage;
const districts=groupsFor(pages) as RegionGroup[];
const published=new Map<string,RegionEntry>(districts.flatMap(d=>d.items).flatMap(entry=>entry.representative.unitKeys.map(key=>[key,entry] as [string,RegionEntry])));
---
<section class="category-hero">
  <span class="eyebrow">{site.brand} {site.region}</span>
  <h1>{site.region} 지역별 꽃배달 안내</h1>
  <p>{site.region}에 전할 위로와 축하의 꽃을 찾고 계신가요? 받는 장소에 맞는 안내를 골라 상품 사진과 기본가격을 살펴보세요. 전하고 싶은 마음을 담아 주문하는 데 필요한 내용을 함께 안내합니다.</p>
  <div class="actions"><a class="btn primary" href={site.phoneHref}>전화 상담·주문</a><a class="btn dark" href={site.orderUrl}>온라인 주문</a></div>
</section>
<nav class="actions" aria-label="지역 안내">{districts.map(d=><a class="btn light" href={`#${d.key}`}>{d.name}</a>)}</nav>
{districts.map((district,index)=><section id={district.key} data-region-district={district.key}>
  <div class="section-title"><h2>{district.name}</h2></div>
  <div class="card-grid big">{district.items.map(({representative,page})=><a class="page-card" href={page.url} data-region-unit={representative.unitKeys.join('|')}><strong>{page.primaryKeyword}</strong><span>{page.cardSummary}</span><em>주문 안내 보기 →</em></a>)}</div>
  {index===Math.floor((districts.length-1)/2) && <InlineOrderBanner/>}
  <details class="content-card"><summary>행정구역 이름으로 찾기</summary>
    <p>익숙한 동 이름으로 찾으실 수 있도록 법정동 {coverage.units.length}개와 행정동 {coverage.administrativeCrosswalk.length}개를 함께 표시했습니다. ‘일부’는 한 법정동이 여러 행정동에 걸친 경우입니다. 개별 주문 안내는 준비된 곳만 연결하며, 배송 가능 여부는 실제 주소로 상담해 주세요.</p>
    <ul class="decision-list">{coverage.administrativeCrosswalk.filter(a=>a.districtKey===district.key).map(admin=><li data-administrative-unit={admin.aliasKey}><strong>{admin.name}</strong>: {admin.relations.map((relation,index)=>{
      const unit=coverage.units.find(unit=>unit.unitKey===relation.unitKey);
      const entry=published.get(relation.unitKey);
      if(!unit)throw new Error('Administrative relation lacks a legal unit');
      return <>{index>0?' · ':''}{entry ? <a href={entry.page.url}>{unit.name}</a> : <span>{unit.name} (개별 안내 준비 중)</span>}{relation.scope==='partial'?' 일부':''}</>;
    })}</li>)}</ul>
    <a href={district.sourceUrl} rel="nofollow">{district.name} 공식 관할 안내</a>
  </details>
</section>)}

src/config/site.ts.utf8Content:
import truth from '../data/business-truth.json';
import architecture from '../data/architecture.json';
import pages from '../data/pages.json';
import config from '../data/site-config.json';
const domain = (import.meta.env.SITE_URL || config.previewUrl).replace(/\/$/, '');
export const site = {
  brand: truth.brand, region: config.region, domain,
  indexable: import.meta.env.SITE_INDEXABLE === 'true' && config.productionApproved === true,
  phone: truth.phone, phoneHref: truth.phoneHref, orderUrl: truth.onlineOrderUrl,
  phoneOrderHours: truth.phoneOrderHours.replace('-', '~'), onlineOrderHours: truth.onlineOrderHours,
  orderHours: `전화 ${truth.phoneOrderHours.replace('-', '~')} · 온라인 ${truth.onlineOrderHours} 접수`,
  deliveryNotice: truth.deliveryNotice, productVariationNotice: truth.productVariationNotice,
  naverVerification: config.naverVerification || ''
};
const publishedPages = pages as {category:string}[];
export const groups = architecture.hubs.filter(h => publishedPages.some(p => p.category === h.category)).map(h => ({cat: h.category, label: h.label, url: h.url}));
export const serviceGroups = groups.filter(group => group.cat !== 'regions');
export const menuGroups = architecture.hubs.filter(h => publishedPages.filter(p => p.category === h.category).length >= 5).map(h => ({cat: h.category, label: h.label, url: h.url}));

src/layouts/BaseLayout.astro.utf8Content:
---
import '../styles/global.css';
import {site,menuGroups} from '../config/site';
import buildRevision from '../data/build-revision.json';
import products from '../data/products.json';
import provenance from '../data/social-image-provenance.json';
import {productSocialImage} from '../lib/social-image.mjs';
const {title,description,canonicalPath='/',noindex=false,includeSchema=true,orderUrl=site.orderUrl,socialProduct=products[0]}=Astro.props;
const canonical=canonicalPath===false ? '' : new URL(canonicalPath,site.domain).toString();
const socialImage=canonical ? productSocialImage(socialProduct,provenance,site.domain,site.brand) : null;
const indexable=site.indexable && !noindex;
const robots=site.indexable && canonical ? (noindex ? 'noindex,follow' : 'index,follow') : 'noindex,nofollow,noarchive';
const revision=buildRevision.revision || 'local';
---
<!doctype html><html lang="ko"><head>
<meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>{title}</title><meta name="description" content={description}/>
<meta name="robots" content={robots}/>
{indexable && <meta name="naver-site-verification" content={site.naverVerification}/>}
<meta name="site-factory-revision" content={revision}/>{canonical && <link rel="canonical" href={canonical}/>}
{canonical && <><meta property="og:type" content="website"/><meta property="og:title" content={title}/><meta property="og:description" content={description}/><meta property="og:url" content={canonical}/><meta property="og:locale" content="ko_KR"/></>}
{socialImage && <><meta property="og:image" content={socialImage.url}/><meta property="og:image:secure_url" content={socialImage.url}/><meta property="og:image:alt" content={socialImage.alt}/><meta property="og:image:type" content={socialImage.type}/><meta property="og:image:width" content={socialImage.width}/><meta property="og:image:height" content={socialImage.height}/><meta name="twitter:image" content={socialImage.url}/><meta name="twitter:image:alt" content={socialImage.alt}/></>}
<meta name="twitter:card" content="summary"/><meta name="twitter:title" content={title}/><meta name="twitter:description" content={description}/>
<meta name="theme-color" content="#3a214f"/>
{includeSchema && <script type="application/ld+json" set:html={JSON.stringify({'@context':'https://schema.org','@type':'Florist',name:site.brand,url:site.domain,telephone:site.phone,areaServed:site.region}).replace(/</g, String.fromCharCode(92) + 'u003c')}></script>}
</head><body>
<a class="skip-link" href="#main-content">본문 바로가기</a>
<header class="site-header"><div class="header-inner"><a class="brand" href="/"><span class="brand-icon">✿</span><span><b>{site.brand}</b><small>{site.region} 꽃배달</small></span></a>
<nav aria-label="주요 메뉴">{menuGroups.map(g=><a href={g.url}>{g.label}</a>)}</nav><a class="phone" href={site.phoneHref}>☎ {site.phone}</a></div></header>
<main id="main-content"><slot/></main>
<footer><div><strong>{site.brand} {site.region}</strong><span>{site.orderHours}</span><a href={site.phoneHref}>{site.phone}</a><a href={orderUrl}>온라인 주문</a></div></footer>
<div class="mobile-bar"><a href={site.phoneHref}>전화주문</a><a href={orderUrl}>온라인 주문</a></div>
</body></html>

src/lib/catalog.mjs.utf8Content:
/** Map buyer intent to real catalog families. Unknown intent never inherits wreaths. */
export function productFamilies(page) {
  if(page.pageType==='regional-service'){
    if(page.category!=='regions'||!Array.isArray(page.regionalProductFamilies)||!['catalog','consultation-only'].includes(page.regionalPurchaseMode)) throw new Error('Regional service requires reviewed purchase metadata');
    return [...page.regionalProductFamilies];
  }
  if (page.pageType === 'business-opening') return ['congrats'];
  if (['school-event', 'station-transit'].includes(page.pageType)) return ['bouquet'];
  if (['hospital-visit', 'personal-gift'].includes(page.pageType)) return ['bouquet', 'basket'];
  if (page.category === 'funeral' || page.pageType === 'funeral-facility') return ['funeral'];
  if (page.pageType === 'event-venue') {
    if (page.visualIntent === 'event_wreath') return ['congrats'];
    if (page.visualIntent === 'performance_venue') return ['bouquet'];
    return ['bouquet', 'basket', 'congrats'];
  }
  if (['price-guide', 'message-guide', 'order-help'].includes(page.pageType)) {
    const funeral=/근조/.test(page.primaryKeyword || '');
    const congrats=/축하/.test(page.primaryKeyword || '');
    if ((funeral && page.visualIntent==='congrats_wreath') || (congrats && page.visualIntent==='funeral_wreath'))
      throw new Error('Product visual intent contradicts promised wreath family');
    if (funeral && congrats) return ['funeral','congrats'];
    if (page.visualIntent === 'funeral_wreath' || funeral) return ['funeral'];
    if (page.visualIntent === 'congrats_wreath' || congrats) return ['congrats'];
    return /화환/.test(page.primaryKeyword || '') ? ['funeral', 'congrats'] : ['bouquet', 'basket', 'funeral', 'congrats'];
  }
  return [];
}
export function selectProducts(page, products, limit = 3) {
  const families = productFamilies(page);
  const allowedProducts=page.pageType==='regional-service' ? products.filter(p=>(page.regionalProductKeys||[]).includes(p.key)) : products;
  const rows = families.flatMap(family => allowedProducts.filter(p => p.family === family));
  if (families.length === 1) return rows.slice(0, limit);
  const first = families.map(family => rows.find(p => p.family === family)).filter(Boolean);
  return [...first, ...rows.filter(p => !first.includes(p))].slice(0, limit);
}
export function productHeading(page) {
  const families = productFamilies(page);
  if (families.length === 1 && families[0] === 'funeral') return '근조화환 상품과 가격';
  if (families.length === 1 && families[0] === 'congrats') return '축하화환 상품과 가격';
  if (families.length && families.every(f => ['bouquet', 'basket'].includes(f))) return '전달하기 좋은 꽃선물';
  return '목적에 맞는 꽃 상품 비교';
}

/** Active verified wreath selection; unavailable gift families never inherit wreaths. */
export function homeProducts(products) {
  const keys = ['funeral-basic', 'funeral-premium', 'funeral-large', 'funeral-xl', 'congrats-basic', 'congrats-premium', 'congrats-large', 'congrats-xl'];
  return keys.map(key => products.find(p => p.key === key)).filter(Boolean);
}

src/lib/content.mjs.utf8Content:
// Deliberately small Markdown subset. Raw HTML stays text; Astro escapes every token.
export function safeHref(value) {
  if (typeof value !== 'string' || /[\s\u0000-\u001f]/.test(value)) return null;
  if (value.startsWith('/') && !value.startsWith('//') && !value.includes('\\')) return value;
  try { const u = new URL(value); return ['https:', 'http:', 'tel:'].includes(u.protocol) ? value : null; } catch { return null; }
}
export function inlineTokens(text) {
  const parts = []; const re = /\[([^\]]+)\]\(([^)]+)\)|\*\*([^*]+)\*\*/g; let last=0;
  for (const m of text.matchAll(re)) {
    if (m.index > last) parts.push({type:'text', text:text.slice(last,m.index)});
    parts.push(m[3] ? {type:'strong',text:m[3]} : {type:'link',text:m[1],href:safeHref(m[2])}); last=m.index+m[0].length;
  }
  if (last < text.length) parts.push({type:'text',text:text.slice(last)});
  return parts;
}
export function markdownBlocks(markdown) {
  const blocks=[]; let paragraph=[];
  const flush=()=>{if(paragraph.length){blocks.push({type:'p',text:paragraph.join(' ')});paragraph=[];}};
  for(const line of markdown.replace(/\r/g,'').split('\n')) {
    if(!line.trim()){flush();continue;}
    const heading=line.match(/^(#{1,6})\s+(.+)$/);
    const item=line.match(/^(?:[-*]|\d+\.)\s+(.+)$/);
    if(heading){flush();blocks.push({type:heading[1].length<=2?'h2':'h3',text:heading[2]});}
    else if(item){flush();blocks.push({type:'li',text:item[1]});}
    else paragraph.push(line.trim());
  }
  flush(); return blocks;
}

// This renderer creates plain <p> elements from text-only paragraph blocks.
// Match their exact text before escaping; do not decode entities or normalize it.
// Markup-like or uncertain input stays visible, even when its spelling matches.
export function displayMarkdownBlocks(markdown, firstAnswer) {
  const blocks=markdownBlocks(markdown);
  const lead=blocks[0];
  if (!lead || lead.type!=='p' || typeof firstAnswer!=='string' || !firstAnswer.trim()) return blocks;
  const tokens=inlineTokens(lead.text);
  if (tokens.length!==1 || tokens[0].type!=='text' || /[<>&*_`\[\]]|~~/.test(lead.text)) return blocks;
  return lead.text===firstAnswer ? blocks.slice(1) : blocks;
}

