/** Explicit data adapter. Geographic inventory is not permission to publish. */
const fail = reason => { throw new Error(`Regional service: ${reason}`); };
const unique=(items,key)=>{const values=items.map(x=>x[key]);if(values.some(x=>!x)||new Set(values).size!==values.length)fail(`duplicate/missing ${key}`);};
const pathSafe=url=>/^\/[a-z0-9-]+\/[a-z0-9-]+\/$/.test(url);
const official=(value,hosts)=>{try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&hosts.includes(u.hostname);}catch{return false;}};
export const isRegional = page => page.category==='regions'||page.pageType==='regional-service';

/** Gangbuk-only extension. Absence of the mode retains the original unit assignment loop. */
const facilityAssignment='facility-purchase-context-v1';
const facilitySite='seoul-gangbuk-flower-direct';
const facilityScope='seoul-gangbuk-direct-initial-20261011';
const facilityFields=['facilityKey','name','sourceUrl','address','unitKey'];
const facilityContextFields=['facilityKey','purchaseIntentKey','contextKey','intentKey'];
const purchaseIntents=new Set(['funeral-condolence-wreath','wedding-congrats-wreath','opening-congrats-wreath','event-congrats-wreath']);
const kebab=value=>typeof value==='string'&&/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(value);
const own=(record,key)=>record!=null&&Object.hasOwn(record,key);
const same=(left,right)=>JSON.stringify(left)===JSON.stringify(right);
function facilityMode(coverage,policy) {
 const opted=own(coverage,'representativeAssignment')||own(policy,'representativeAssignment');
 if(!opted){
  if(own(coverage,'facilities')||own(policy,'facilities')||(Array.isArray(coverage?.representatives)&&coverage.representatives.some(r=>facilityContextFields.slice(0,3).some(key=>own(r,key)))))fail('facility context requires explicit opt-in');
  return false;
 }
 if(coverage?.representativeAssignment!==facilityAssignment||policy?.representativeAssignment!==facilityAssignment)fail('facility assignment opt-in mismatch');
 if(coverage.siteKey!==facilitySite||policy.siteKey!==facilitySite||coverage.scopeKey!==facilityScope||policy.scopeKey!==facilityScope)fail('facility assignment site/scope mismatch');
 return true;
}
function sourceIdentity(value) {
 if(typeof value!=='string'||!value.startsWith('https://')||!/^[\x21-\x7e]+$/.test(value)||/[\\\s"'<>\{\}|`^]/u.test(value))fail('unsafe facility source URL');
 const authority=value.slice(8).split(/[/?#]/,1)[0];
 if(!authority||/[@%\u0080-\uffff]/u.test(authority))fail('unsafe facility source URL');
 try {
  const url=new URL(value);
  if(url.protocol!=='https:'||url.hostname.length>253||!/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+(?:[a-z]{2,63}|xn--[a-z0-9](?:[a-z0-9-]{0,57}[a-z0-9])?)$/i.test(url.hostname)||url.username||url.password)fail('unsafe facility source URL');
  url.hash='';
  if(!url.search)url.search='';
