}
function facilityRegistry(coverage,units) {
 if(!Array.isArray(coverage.facilities)||!coverage.facilities.length)fail('missing facility registry');
 const registry=new Map(),identities=new Set();
 for(const facility of coverage.facilities){
  if(!facility||typeof facility!=='object'||Array.isArray(facility)||!same(Object.keys(facility).sort(),[...facilityFields].sort()))fail('unknown/missing facility fields');
  if(!kebab(facility.facilityKey)||registry.has(facility.facilityKey))fail('duplicate/invalid facility key');
  if(!units.has(facility.unitKey))fail('unknown facility canonical unit');
  normalizedText(facility.name,'name');
  const identity=JSON.stringify([sourceIdentity(facility.sourceUrl),normalizedText(facility.address,'address')]);
