 if(representative.contextKey!==context||representative.intentKey!=='seoul-gangbuk|'+context||contexts.has(context))fail('duplicate/invalid canonical facility context');
 if(!kebab(representative.slug)||!kebab(representative.pageKey)||!Array.isArray(representative.unitKeys)||!same(representative.unitKeys,[facility.unitKey])||(own(representative,'unitKey')&&representative.unitKey!==facility.unitKey))fail('facility representative canonical unit mismatch');
