 assert.doesNotThrow(()=>runtime.validateRegionalPurchase({...page,purchaseIntentKey:'funeral-condolence-wreath',regionalPurchaseMode:'consultation-only',regionalProductKeys:[],regionalProductFamilies:[]},[]));
});

